package app.streamnest;
import android.content.Context;import java.io.*;import java.nio.charset.StandardCharsets;
/** Supply libass a small private fontconfig cache on Android builds without a default config. */
final class SubtitleFonts {
 static boolean ready;
 static synchronized void configure(Context context){if(ready)return;try{File source=null;for(String path:new String[]{"/system/fonts/Roboto-Regular.ttf","/system/fonts/NotoSans-Regular.ttf","/system/fonts/DroidSans.ttf"})if(new File(path).isFile()){source=new File(path);break;}if(source==null)return;File directory=new File(context.getFilesDir(),"subtitle-fonts");if(!directory.isDirectory()&&!directory.mkdirs())return;File font=new File(directory,source.getName());if(!font.isFile()||font.length()!=source.length())java.nio.file.Files.copy(source.toPath(),font.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);File[] systemFonts=new File("/system/fonts").listFiles((dir,name)->name.startsWith("NotoSansDevanagari")&&name.endsWith(".ttf"));if(systemFonts!=null)for(File extra:systemFonts){File target=new File(directory,extra.getName());if(extra.length()<2000000&&(!target.isFile()||target.length()!=extra.length()))java.nio.file.Files.copy(extra.toPath(),target.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}File cache=new File(directory,"cache");cache.mkdirs();File config=new File(directory,"fonts.conf");String xml="<?xml version=\"1.0\"?><fontconfig><dir>"+directory.getAbsolutePath()+"</dir><cachedir>"+cache.getAbsolutePath()+"</cachedir><alias><family>Arial</family><prefer><family>Roboto</family><family>Noto Sans</family><family>Droid Sans</family></prefer></alias></fontconfig>";java.nio.file.Files.write(config.toPath(),xml.getBytes(StandardCharsets.UTF_8));android.system.Os.setenv("FONTCONFIG_FILE",config.getAbsolutePath(),true);ready=true;}catch(Exception ignored){/* Existing embedded fonts and native renderer fallback remain available. */}}
}
